mapper.update:
UPDATE user_task
SET status = 1,
    progress = 1,
    completed_at = NOW(),
    updated_at = NOW()
WHERE user_id = #{userId}
  AND task_id = #{taskId}
  AND period_key = #{periodKey}
  AND status = 0

UPDATE user_task
SET status = 2,
    claimed_at = NOW(),
    points_awarded = #{pointsAwarded},
    updated_at = NOW()
WHERE user_id = #{userId}
  AND task_id = #{taskId}
  AND period_key = #{periodKey}
  AND status = 1

